function ToolWrapper(props) {
  const [isExpanded, setIsExpanded] = React.useState(true);
  const { toolName, children } = props;

  const TOOL_CONFIGS = {
    gmail: {
      logo: '📧',
      label: 'Gmail',
    },
    'google-calendar': {
      logo: '📅',
      label: 'Google Calendar',
    },
    notion: {
      logo: '📝',
      label: 'Notion',
    },
    stripe: {
      logo: '💳',
      label: 'Stripe',
    },
    openweather: {
      logo: '🌤️',
      label: 'OpenWeather',
    },
    perplexity: {
      logo: '🔍',
      label: 'Perplexity',
    },
    'google-drive': {
      logo: '📁',
      label: 'Google Drive',
    },
    linear: {
      logo: '📊',
      label: 'Linear',
    },
    confluence: {
      logo: '📄',
      label: 'Confluence',
    },
    jira: {
      logo: '🎫',
      label: 'Jira',
    },
    outlook: {
      logo: '✉️',
      label: 'Outlook',
    },
  };

  const toolConfig = TOOL_CONFIGS[toolName] || { logo: '🔧', label: toolName };

  const styles = {
    container: {
      border: '1px solid #e2e8f0',
      borderRadius: '8px',
      overflow: 'hidden',
      marginBottom: '16px',
      fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif',
      width: '100%',
    },
    header: {
      display: 'flex',
      alignItems: 'center',
      padding: '8px 12px',
      backgroundColor: '#f8fafc',
      cursor: 'pointer',
      borderBottom: isExpanded ? '1px solid #e2e8f0' : 'none',
      width: '100%',
    },
    chevron: {
      marginRight: '8px',
      fontSize: '14px',
      transition: 'transform 0.2s',
    },
    logoContainer: {
      marginRight: '8px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      fontSize: '16px',
    },
    label: {
      fontWeight: '500',
      fontSize: '14px',
      color: 'black',
    },
    content: {
      padding: isExpanded ? '16px' : '0',
      height: isExpanded ? 'auto' : '0',
      overflow: 'hidden',
      transition: 'height 0.2s ease, padding 0.2s ease',
      width: '100%',
    },
    componentsContainer: {
      display: 'flex',
      flexWrap: 'wrap',
      gap: '16px',
      width: '100%',
    }
  };

  // Create a ref for measuring content
  const contentRef = React.useRef(null);

  // Render child components
  const renderChildren = () => {
    if (!children) return null;

    // If children is an array of components
    if (Array.isArray(children)) {
      return React.createElement('div', { style: styles.componentsContainer },
        children.map((child, index) => {
          if (!child.jsx) return null;

          try {
            const ChildComponent = new Function(
              'React', 
              'props', 
              `const Comp = ${child.jsx}; return Comp(props);`
            );
            return React.createElement('div', { key: index }, ChildComponent(React, child.props));
          } catch (error) {
            console.error('Error rendering child component:', error);
            return React.createElement('div', { key: index }, 'Error rendering component');
          }
        })
      );
    }

    // If children is a single component with jsx
    if (children.jsx) {
      try {
        const ChildComponent = new Function(
          'React', 
          'props', 
          `const Comp = ${children.jsx}; return Comp(props);`
        );
        return ChildComponent(React, children.props);
      } catch (error) {
        console.error('Error rendering child component:', error);
        return React.createElement('div', {}, 'Error rendering component');
      }
    }

    // If this is just a React element or text
    return children;
  };

  return React.createElement('div', { style: styles.container },
    React.createElement('div', { 
      style: styles.header,
      onClick: () => setIsExpanded(!isExpanded)
    },
      React.createElement('span', { style: styles.chevron }, isExpanded ? '▼' : '▶'),
      React.createElement('div', { style: styles.logoContainer }, toolConfig.logo),
      React.createElement('span', { style: styles.label }, toolConfig.label)
    ),
    React.createElement('div', { 
      ref: contentRef,
      style: styles.content 
    }, renderChildren())
  );
}
